// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess, address actor, uint256 startBlock) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // keep block numbers in a safe (overflow-free) range so the reference never panics
        uint256 b = bound(startBlock, 1, type(uint256).max - 2);
        vm.roll(b);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        // one block after the lock-in: target block is not yet reached in the reference
        vm.roll(b + 1);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // General rule: settle one block after locking always reverts in C;
        // the mutant (target = lock-in block) lets settle succeed here.
        assertTrue(!ok, "settle must revert when called one block after lock-in");
    }
}
